    if (t ? emptyText) {
      "null"
    } else if (t ? base10) {
      t * 1
    } else {
      local stripped = if (t.startsWith("+") || t.startsWith("-")) {
        t.segment(2, t.textLen() - 1)
      } else {
        t
      }
      if (stripped ? base10) {
        t * 1
      } else {
        "null"
      }
    }
  }

